package com.example.urlshortener.orchestration.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="policy_evaluations")
public class PolicyEvaluation { @Id private UUID id; @Column(nullable=false) private UUID runId; @Column(nullable=false,length=30) private String policyVersion; @Column(nullable=false,length=80) private String policy; @Column(nullable=false,length=30) private String outcome; @Column(nullable=false) private boolean mandatory; @Column(nullable=false) private Instant evaluatedAt; @Column(columnDefinition="text") private String reason; protected PolicyEvaluation(){} public PolicyEvaluation(UUID runId,String pv,String policy,String outcome,boolean mandatory,String reason){this.id=UUID.randomUUID();this.runId=runId;this.policyVersion=pv;this.policy=policy;this.outcome=outcome;this.mandatory=mandatory;this.reason=reason;this.evaluatedAt=Instant.now();} public UUID getId(){return id;} public UUID getRunId(){return runId;} public String getPolicyVersion(){return policyVersion;} public String getPolicy(){return policy;} public String getOutcome(){return outcome;} public boolean isMandatory(){return mandatory;} public Instant getEvaluatedAt(){return evaluatedAt;} public String getReason(){return reason;}}
